require_once __DIR__.'/../config.php'; require_admin(); if($_SERVER['REQUEST_METHOD']!=='POST'){header('Location: index.php');exit;} verify_csrf(); $id=(int)($_POST['user_id']??0); $action=$_POST['action']??''; if($id<=0||!in_array($action,['disable','enable'],true)){header('Location: index.php');exit;} $status=$action==='disable'?'disabled':'active'; $stmt=db()->prepare("UPDATE users SET status=? WHERE id=? AND role='student'"); $stmt->execute([$status,$id]); log_event((int)current_user()['id'],'account_'.$action,'Student account ID '.$id); header('Location: index.php'); exit;
